const { Routes } = require('discord-api-types/v9');
const { Collection } = require('discord.js');
const { Client, Intents } = require('discord.js');

// Import your bot's token and guild ID(s)
const { TOKEN, GUILD_ID } = require('./config.json');

// Create a new Discord client
const client = new Client({ intents: [Intents.FLAGS.GUILDS] });

// Define a collection to store commands
const commands = new Collection();

// Define a function to register commands
function registerCommands() {
  const rest = new REST({ version: '9' }).setToken(TOKEN);

  (async () => {
    try {
      // Register global commands
      await rest.put(Routes.applicationCommands(GUILD_ID), { body: commands.cache.data });

      console.log('Global commands registered successfully.');
    } catch (error) {
      console.error(error);
    }
  })();
}

